"""Retos propios y entradas identificadas desde las redes. Sin seguimiento adicional."""
import html
from hashlib import sha256
from pathlib import Path

def pages(shell, write, url, updated):
    css = '''<style>
.challenge-head{max-width:760px}.challenge-head .lede{font-size:1.1rem}.challenge-grid{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(240px,1fr);gap:24px;margin:28px 0}.quiz-card,.challenge-card{border:1px solid var(--line);border-radius:20px;padding:26px;background:#1b1028}.quiz-modes{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.quiz-modes button,.quiz-answer{border:1px solid #6d506d;background:#291831;color:#fff;border-radius:12px;padding:14px 18px;font:inherit;cursor:pointer}.quiz-modes [aria-pressed="true"]{background:var(--flamingo);color:#180d23;border-color:var(--flamingo);font-weight:700}.quiz-answer{width:100%;text-align:left;margin:7px 0}.quiz-answer:hover:not(:disabled){border-color:var(--peach);background:#40223e}.quiz-answer.correct{border-color:#7fffc5;background:#133d32}.quiz-answer.incorrect{border-color:#ff98ad;background:#482132}.quiz-answer:disabled{opacity:1;cursor:default}.quiz-card h2{font:800 clamp(1.5rem,3vw,2.05rem)/1.15 var(--font-display);transform:none;text-shadow:none;color:#fff;margin:18px 0}.quiz-feedback{min-height:75px;line-height:1.6;color:#e9d6e4}.quiz-scene{height:130px;position:relative;overflow:hidden;border-radius:12px;background:linear-gradient(#493383,#ffb387);isolation:isolate}.quiz-scene::before{content:"";position:absolute;inset:25% 0 0;background:repeating-linear-gradient(90deg,#1b1433 0 8%,transparent 8% 12%);clip-path:polygon(0 50%,10% 50%,10% 15%,23% 15%,23% 40%,35% 40%,35% 0,47% 0,47% 30%,63% 30%,63% 10%,76% 10%,76% 55%,88% 55%,88% 25%,100% 25%,100% 100%,0 100%)}.quiz-scene::after{content:"";position:absolute;bottom:12px;width:36px;height:9px;border-radius:7px;background:#7fffc5;box-shadow:0 0 20px #7fffc5;animation:drive 5s linear infinite}.quiz-scene span{position:absolute;top:12px;left:14px;font:500 .65rem var(--font-mono);color:#fff}.quiz-card[data-scene="swamp"] .quiz-scene{background:linear-gradient(#173d41,#83bba0)}.quiz-card[data-scene="swamp"] .quiz-scene::before{background:#142c2b;clip-path:polygon(0 75%,9% 35%,17% 75%,25% 20%,34% 70%,45% 28%,55% 77%,65% 35%,77% 78%,88% 18%,100% 75%,100% 100%,0 100%)}.quiz-card[data-scene="mountain"] .quiz-scene{background:linear-gradient(#344969,#f5ac9f)}.quiz-card[data-scene="mountain"] .quiz-scene::before{background:#273645;clip-path:polygon(0 100%,20% 50%,32% 65%,52% 0,78% 65%,89% 45%,100% 100%)}.challenge-card h2{font:800 1.7rem var(--font-display);margin:0 0 10px;transform:none;text-shadow:none}.challenge-card p{line-height:1.65}.challenge-card a{display:inline-block;margin-top:8px}.challenge-side{display:grid;gap:18px;align-content:start}.challenge-note{font-size:.85rem;color:var(--muted);line-height:1.7}#quizResult[hidden],#quizNext[hidden]{display:none}@keyframes drive{from{transform:translateX(-50px)}to{transform:translateX(800px)}}@media(prefers-reduced-motion:reduce){.quiz-scene::after{animation:none;left:40%}}@media(max-width:760px){.challenge-grid{grid-template-columns:1fr}.quiz-card,.challenge-card{padding:20px}.static main{padding-top:32px}}
</style>'''
    body = '''<p class="crumbs"><a href="../">LeonidaDex</a> › Retos</p>
<div class="challenge-head"><p class="eyebrow">El reto del copiloto</p><h1>¿Cuánto conoces Leonida?</h1><p class="lede">Tres preguntas. Cero spoilers de la historia. Elige regiones o personajes y comprueba si te vienes de copiloto.</p></div>
<div class="challenge-grid"><section class="quiz-card" id="leonidaQuiz" aria-label="Cuestionario de GTA VI" data-scene="city">
<div class="quiz-modes" role="group" aria-label="Elegir reto"><button type="button" data-quiz-mode="regiones" aria-pressed="true">Regiones</button><button type="button" data-quiz-mode="personajes" aria-pressed="false">Personajes</button></div>
<div class="quiz-scene" aria-hidden="true"><span>POSTAL ILUSTRADA · LEONIDADEX</span></div>
<p class="eyebrow" id="quizProgress">Activa JavaScript para jugar</p><h2 id="quizQuestion" tabindex="-1">Elige tu reto</h2><div id="quizAnswers"></div><p class="quiz-feedback" id="quizFeedback" role="status" aria-live="polite"></p>
<button type="button" class="btn btn-primary" id="quizNext" hidden>Siguiente pregunta</button><div id="quizResult" hidden><h3>Reta a tu grupo</h3><p>Comparte tu nota y que tus colegas prueben el mismo reto. Tú eliges el destinatario y confirmas el envío.</p><div class="quiz-share-actions"><button type="button" class="btn btn-primary" id="quizShare" hidden>Compartir mi resultado</button><a class="btn btn-primary" id="quizWhatsApp" target="_blank" rel="noopener noreferrer">Compartir por WhatsApp</a><button type="button" class="btn btn-ghost" id="quizCopy">Copiar mi resultado</button></div></div>
<noscript><p>Para jugar necesitas JavaScript. Puedes consultar las <a href="../leonida/">regiones</a> y los <a href="../personajes/">personajes</a> sin activarlo.</p></noscript></section>
<aside class="challenge-side" aria-label="Sigue explorando"><section class="challenge-card"><p class="eyebrow">01 · Explora</p><h2>Tu próxima parada</h2><p>Abre el mapa, busca un lugar y consulta su procedencia. Sus identificaciones comunitarias no son coordenadas oficiales de Rockstar.</p><a class="btn btn-primary" href="../#mapa" data-ld-action="ld_map_open" data-ld-content="mapa">Abrir el mapa</a></section>
<section class="challenge-card"><p class="eyebrow">02 · Conoce al grupo</p><h2>¿Con quién te subes?</h2><p>Jason, Lucia, Cal y el resto. Fichas de presentación con enlaces a sus fuentes.</p><a class="btn btn-ghost" href="../personajes/" data-ld-action="ld_character_open" data-ld-content="fichas">Ver personajes</a></section></aside></div>
<p class="challenge-note">Preguntas basadas en la presentación pública de <a href="https://www.rockstargames.com/VI/only-in-leonida" target="_blank" rel="noopener">personajes y lugares de Rockstar</a>. Las postales son ilustraciones propias, no capturas del juego. No necesitas registro ni aceptar la medición para jugar. El resultado se mantiene solo mientras usas esta página.</p>
<script src="../assets/retos.js" defer></script>'''
    page_url = url + 'retos/'
    css = css.replace('</style>', '.quiz-share-actions{display:flex;gap:12px;flex-wrap:wrap}.quiz-share-actions .btn{max-width:100%;white-space:normal}#quizShare[hidden]{display:none}#quizResult h3{margin:8px 0}#quizResult p{line-height:1.6}</style>')
    version = sha256((Path(__file__).parent / 'src/assets/retos.js').read_bytes()).hexdigest()[:12]
    body = body.replace('src="../assets/retos.js"', 'src="../assets/retos.js?v='+version+'"')
    text = shell(1, 'Retos de GTA VI: regiones y personajes | LeonidaDex', 'Pon a prueba lo que sabes de Leonida con nuestros retos de regiones y personajes. Gratis, sin registro y sin spoilers de la historia.', page_url, css+body)
    text = text.replace(url+'assets/leonidadex-social.jpg', url+'assets/retos-social.jpg')
    text = text.replace('LeonidaDex: el caimán de Leonida y la guía de GTA VI en español', 'El reto del copiloto de LeonidaDex: tres preguntas de GTA VI, regiones y personajes')
    write('retos/index.html', text)
    urls=[(page_url,updated)]
    for source in ('tiktok','youtube'):
        target='../retos/?utm_source='+source+'&utm_medium=social&utm_campaign=leonida_retos&utm_content=perfil'
        content='<p class="crumbs"><a href="../">LeonidaDex</a></p><h1>Tu reto de Leonida te espera</h1><p>Te llevamos a los retos. Si no se abre automáticamente, pulsa aquí.</p><a class="btn btn-primary" href="'+html.escape(target)+'">Entrar a los retos</a><script src="../assets/campana.js" data-source="'+source+'" defer></script>'
        text=shell(1,'Desde '+source.title()+' a LeonidaDex','Mapa, retos y fichas de GTA VI.',page_url,content)
        text=text.replace('</head>','<meta name="robots" content="noindex,follow">\n</head>')
        write(source+'/index.html',text)
    return urls
